package com.wizzadrds.theworldremembers; import com.wizzadrds.theworldremembers.knowledge.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes; public final class KnowledgeWitnessGameTest{@GameTest public void nearbyVillagerWitnessesDeath(GameTestHelper c){var dead=c.spawn(EntityTypes.VILLAGER,2,1,2);var witness=c.spawn(EntityTypes.VILLAGER,4,1,2);c.runAtTickTime(1,()->{TheWorldRemembers.processWorld(c.getLevel());dead.kill();c.runAtTickTime(2,()->{var facts=KnowledgeManager.get(c.getLevel().getServer()).factsOf(witness.getUUID());if(facts.stream().noneMatch(f->f.origin()==KnowledgeOrigin.DIRECT&&f.type().equals("npc_died"))){c.fail("Witness did not receive direct knowledge");return;}c.succeed();});});}}